{"status":"candidate","chosen_option":"tree_dp","assumptions":["The input edges form a connected acyclic tree, as specified.","C++17 is an acceptable implementation language."],"observations":[{"statement":"The task allows up to 200,000 vertices and costs up to 1,000,000,000, so the implementation uses 64-bit costs.","source_ids":["task"]},{"statement":"The supplied examples specify outputs 0 for the one-vertex case and 5 for the six-vertex case.","source_ids":["public1","public2"]}],"artifact":{"code":"#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> cost(n);
    for (auto &c : cost) cin >> c;

    vector<vector<int>> graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Build a traversal order iteratively to avoid recursion-depth limits.
    vector<int> parent(n, -1), order;
    order.reserve(n);
    parent[0] = 0;
    order.push_back(0);
    for (size_t i = 0; i < order.size(); ++i) {
        int u = order[i];
        for (int v : graph[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            order.push_back(v);
        }
    }

    // dp0[u]: minimum cost in u's subtree when u is not selected.
    // dp1[u]: minimum cost in u's subtree when u is selected.
    vector<long long> dp0(n, 0), dp1(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];
        dp1[u] = cost[u];
        for (int v : graph[u]) {
            if (parent[v] != u) continue;
            dp0[u] += dp1[v];
            dp1[u] += min(dp0[v], dp1[v]);
        }
    }

    cout << min(dp0[0], dp1[0]) << '\n';
    return 0;
}"} }
